def values(self, *keys):
    """Return the values of the record, optionally filtering to include
    only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none are
                 provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Attempt to obtain stored data for this record.  Most record
    # implementations keep their items in an OrderedDict-like object
    # named `_data`.  If a different name is used, the caller can
    # adapt the method accordingly.
    if not hasattr(self, "_data"):
        raise AttributeError(
            "Record object does not expose a `_data` attribute "
            "containing its key/value pairs."
        )
    data = self._data

    # If no keys are provided simply return all values in order.
    if len(keys) == 0:
        # `data` may be a dict- or OrderedDict-like object.
        return list(data.values())

    # Build the list of requested values.
    items = list(data.items())   # preserve order for index-based access
    result = []

    for k in keys:
        if isinstance(k, int):
            # Index-based lookup.  Accept negative indices as Python
            # sequence semantics.
            try:
                result.append(items[k][1])
            except IndexError as exc:
                raise IndexError(f"Index {k} is out of range for the record") from exc
        else:
            # Key-based lookup.
            if k in data:
                result.append(data[k])
            else:
                raise KeyError(f"Key {k!r} not found in the record")

    return result

