def _c_optimizations_required():
    """
    Return a true value if the C optimizations are required.

    This function uses the `PURE_PYTHON` variable to determine whether a pure
    Python implementation is in use. If `PURE_PYTHON` is truthy, no C
    optimizations should be applied; otherwise the C optimizations are
    required.
    """
