def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    :return: The modified dict with coerced values.
    """
    if not isinstance(values_dict, dict):
        # nothing to do if not a dict
        return values_dict

    # Helper functions to detect types
    def _is_int(val):
        try:
            int(val)
            # disallow floats that look like ints
            return True
        except Exception:
            return False

    def _is_float(val):
        try:
            float(val)
            return True
        except Exception:
            return False

    def _is_bool(val):
        return val.lower() in ("true", "false", "yes", "no", "1", "0")

    def _to_bool(val):
        if val.lower() in ("true", "yes", "1"):
            return True
        return False

    for key, value in list(values_dict.items()):
        # Only handle string-like values
        if not isinstance(value, str):
            continue
        val = value.strip()
        if val == "":
            continue
        # List detection: comma separated
        if "," in val:
            # Split and strip each element
            lst = [elem.strip() for elem in val.split(",") if elem.strip() != ""]
            values_dict[key] = lst
            continue
        # Boolean detection
        if _is_bool(val):
            values_dict[key] = _to_bool(val)
            continue
        # Integer detection
        if _is_int(val):
            try:
                values_dict[key] = int(val)
                continue
            except Exception:
                pass
        # Float detection
        if _is_float(val):
            try:
                values_dict[key] = float(val)
                continue
            except Exception:
                pass
        # Leave as string otherwise
    return values_dict

